type IconName = 'home'|'user'|'food'|'meal'|'workout'|'progress'|'report'|'notes'|'settings'|'moon'|'sun'|'arrow'|'plus'|'trash'|'download'|'upload'|'check'|'search'|'calendar'|'clock'|'scale'|'edit'|'heart'|'backup';
