 function addWorkout(e:FormEvent){e.preventDefault();if(!workName.trim()||Number(workMinutes)<=0){setToast('اكتب اسم التمرين والمدة.');return;}setData(d=>({...d,workouts:[{id:uid(),date:workDate,name:workName.trim(),place:workPlace,minutes:Number(workMinutes),notes:workNotes.trim()},...d.workouts]}));setWorkNotes('');setToast('تم تسجيل التمرين.');}
 function youtubeEmbed(raw:string):string|null{try{const u=new URL(raw.trim());let id='';if(u.hostname.includes('youtu.be'))id=u.pathname.slice(1).split('/')[0];else if(u.hostname.includes('youtube.com')){if(u.pathname==='/watch')id=u.searchParams.get('v')||'';else if(u.pathname.startsWith('/embed/'))id=u.pathname.split('/')[2]||'';else if(u.pathname.startsWith('/shorts/'))id=u.pathname.split('/')[2]||'';}return /^[a-zA-Z0-9_-]{11}$/.test(id)?`https://www.youtube-nocookie.com/embed/${id}`:null;}catch{return null;}}
 async function addWorkoutVideo(e:FormEvent){e.preventDefault();if(!videoName.trim()){setToast('اكتب اسم الفيديو.');return;}const old=editingVideoId?videoItems.find(v=>v.id===editingVideoId):undefined;let blob:Blob|undefined;let url:string|undefined;let youtubeUrl:string|undefined;if(videoSource==='file'){blob=videoFile||old?.blob;if(!blob){setToast('اختار ملف فيديو من جهازك.');return;}if(videoFile&&videoFile.size>100*1024*1024){setToast('حجم الفيديو أكبر من 100 ميجابايت؛ اختار فيديو أصغر.');return;}url=old?.url;if(videoFile)url=URL.createObjectURL(videoFile);}else{const embed=youtubeEmbed(videoLink);if(!embed){setToast('الرابط مش واضح كرابط YouTube صالح. انسخ رابط الفيديو الأصلي.');return;}youtubeUrl=videoLink.trim();}const item:WorkoutVideo={id:editingVideoId||uid(),name:videoName.trim(),exercise:videoExercise.trim(),category:videoCategory,source:videoSource,youtubeUrl,date:old?.date||today(),blob,url};try{await saveWorkoutVideo(item);setVideoItems(items=>old?items.map(v=>v.id===item.id?item:v):[item,...items]);if(old?.url&&old.url!==url)URL.revokeObjectURL(old.url);setVideoName('');setVideoExercise('');setVideoCategory('workout');setVideoSource('file');setVideoLink('');setVideoFile(null);setEditingVideoId('');if(videoRef.current)videoRef.current.value='';setToast(old?'تم تعديل بيانات الفيديو.':'تم حفظ الفيديو في المكتبة.');}catch{setToast('تعذر حفظ الفيديو؛ قد تكون مساحة التخزين غير كافية.');}}
